#!/usr/bin/env python3
"""Compose tiled SAM mask visualization videos for nuScenes clips.

This script mirrors the interface style of ``tools/compose_depth_grid.py`` but
targets semantic masks generated by SAM for the GT data only. It gathers
per-frame PNG masks from

    data/nuscenes_trainval/processed_gt/advanced_12Hz_trainval/{clip}/sam_mask/

and builds a single MP4 video that tiles the requested cameras (typically all
six nuScenes cameras) without any gaps between tiles.
"""

from __future__ import annotations

import argparse
import os
import shutil
import subprocess
from pathlib import Path
from typing import List


CAMERA_NAME_TO_ID = {
    "CAM_FRONT": 0,
    "CAM_FRONT_LEFT": 1,
    "CAM_FRONT_RIGHT": 2,
    "CAM_BACK_LEFT": 3,
    "CAM_BACK_RIGHT": 4,
    "CAM_BACK": 5,
}

CAMERA_ID_TO_NAME = {idx: name for name, idx in CAMERA_NAME_TO_ID.items()}


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser("Compose SAM mask video for a nuScenes clip")
    parser.add_argument("clip_id", type=str, help="Clip identifier (e.g., 002)")
    parser.add_argument(
        "--mask-root",
        type=Path,
        default=Path("data/nuscenes_trainval/processed_gt/advanced_12Hz_trainval"),
        help=(
            "Root directory that contains per-clip SAM masks. "
            "Default matches processed nuScenes GT layout."
        ),
    )
    parser.add_argument(
        "--cameras",
        type=str,
        default="all",
        help=(
            "Comma-separated camera names (e.g. CAM_FRONT,CAM_BACK). "
            "Use 'all' (default) to include every camera."
        ),
    )
    parser.add_argument(
        "--fps",
        type=float,
        default=12.0,
        help="Frame rate for the output video (default: 12.0)",
    )
    parser.add_argument(
        "--output",
        type=Path,
        default=None,
        help=(
            "Output MP4 path (default: work_dirs/sam_mask_videos/clip_{clip}_sam_masks.mp4)"
        ),
    )
    parser.add_argument(
        "--ffmpeg-bin",
        type=str,
        default="ffmpeg",
        help="FFmpeg executable to use (default: ffmpeg)",
    )
    parser.add_argument(
        "--codec",
        type=str,
        default=None,
        help="Optional FFmpeg encoder (e.g. libx264)",
    )
    parser.add_argument(
        "--bitrate",
        type=str,
        default="10M",
        help="Bitrate to use with bitrate-based encoders (default: 10M)",
    )
    parser.add_argument(
        "--verbose",
        action="store_true",
        help="Print FFmpeg commands before execution",
    )
    return parser.parse_args()


def resolve_ffmpeg(binary: str) -> str:
    for cand in [binary, os.environ.get("FFMPEG_BIN"), "ffmpeg"]:
        if cand and shutil.which(cand):
            return cand
    raise SystemExit("FFmpeg not found; install ffmpeg or set --ffmpeg-bin/FFMPEG_BIN")


def normalize_camera_name(name: str) -> str:
    token = name.strip().upper()
    if not token:
        raise ValueError("Empty camera name provided")
    if not token.startswith("CAM_"):
        token = "CAM_" + token
    if token not in CAMERA_NAME_TO_ID:
        raise ValueError(f"Unknown camera name '{name}'")
    return token


def parse_camera_list(raw: str) -> List[str]:
    if raw.lower() == "all":
        return [CAMERA_ID_TO_NAME[idx] for idx in sorted(CAMERA_ID_TO_NAME)]
    cameras: List[str] = []
    for part in raw.split(","):
        if not part.strip():
            continue
        cam = normalize_camera_name(part)
        if cam not in cameras:
            cameras.append(cam)
    if not cameras:
        raise SystemExit("No valid cameras specified via --cameras")
    return cameras


def collect_frame_paths(mask_dir: Path, cam_id: int) -> List[Path]:
    return sorted(mask_dir.glob(f"*_{cam_id}.png"))


def grid_shape(n: int) -> tuple[int, int]:
    if n <= 0:
        raise ValueError("grid_shape requires at least one input")
    cols = max(1, int(round(n ** 0.5)))
    while cols * cols < n:
        cols += 1
    rows = (n + cols - 1) // cols
    return rows, cols


def build_filter_complex(num_inputs: int) -> tuple[str, str]:
    rows, cols = grid_shape(num_inputs)
    cmds: List[str] = []
    row_labels: List[str] = []
    idx = 0
    row_idx = 0
    while idx < num_inputs:
        count = min(cols, num_inputs - idx)
        inputs_concat = "".join(f"[{i}:v]" for i in range(idx, idx + count))
        row_label = f"row{row_idx}"
        if count == 1:
            cmds.append(f"{inputs_concat}null[{row_label}]")
        else:
            cmds.append(f"{inputs_concat}hstack=inputs={count}[{row_label}]")
        row_labels.append(row_label)
        idx += count
        row_idx += 1
    if len(row_labels) == 1:
        final_label = row_labels[0]
    else:
        final_label = "stacked"
        inputs_concat = "".join(f"[{label}]" for label in row_labels)
        cmds.append(f"{inputs_concat}vstack=inputs={len(row_labels)}[{final_label}]")
    return ";".join(cmds), final_label


def build_ffmpeg_cmd(
    ffmpeg: str,
    patterns: List[Path],
    fps: float,
    output: Path,
    codec: str | None,
    bitrate: str,
    filter_complex: str,
    final_label: str,
) -> List[str]:
    cmd: List[str] = [ffmpeg, "-y"]
    for pattern in patterns:
        cmd.extend(["-framerate", str(fps), "-pattern_type", "glob", "-i", str(pattern)])
    cmd.extend(["-filter_complex", filter_complex, "-map", f"[{final_label}]", "-pix_fmt", "yuv420p", "-an"])
    if codec:
        cmd.extend(["-c:v", codec])
        if codec == "libx264":
            cmd.extend(["-preset", "medium", "-crf", "18"])
        elif codec in {"libopenh264", "mpeg4"}:
            cmd.extend(["-b:v", bitrate])
    cmd.append(str(output))
    return cmd


def main() -> None:
    args = parse_args()
    ffmpeg = resolve_ffmpeg(args.ffmpeg_bin)

    clip_dir = args.mask_root / args.clip_id / "sam_mask"
    if not clip_dir.is_dir():
        raise SystemExit(f"Mask directory does not exist: {clip_dir}")

    cameras = parse_camera_list(args.cameras)
    frame_counts: List[int] = []
    patterns: List[Path] = []

    for camera in cameras:
        cam_id = CAMERA_NAME_TO_ID[camera]
        frames = collect_frame_paths(clip_dir, cam_id)
        if not frames:
            raise SystemExit(f"No SAM mask frames found for camera {camera} in {clip_dir}")
        frame_counts.append(len(frames))
        patterns.append(clip_dir / f"*_{cam_id}.png")

    if len(set(frame_counts)) != 1:
        raise SystemExit(
            "Frame count mismatch across cameras: "
            + ", ".join(f"{cam}={cnt}" for cam, cnt in zip(cameras, frame_counts))
        )

    filter_complex, final_label = build_filter_complex(len(cameras))

    if args.output is None:
        out_dir = Path("work_dirs") / "sam_mask_videos"
        out_dir.mkdir(parents=True, exist_ok=True)
        out_path = out_dir / f"clip_{args.clip_id}_sam_masks.mp4"
    else:
        out_path = args.output
        out_path.parent.mkdir(parents=True, exist_ok=True)

    cmd = build_ffmpeg_cmd(
        ffmpeg,
        patterns,
        args.fps,
        out_path,
        args.codec,
        args.bitrate,
        filter_complex,
        final_label,
    )
    if args.verbose:
        print("FFmpeg command:")
        print(" ".join(cmd))
    subprocess.run(cmd, check=True)
    print(
        f"Saved tiled SAM mask video ({frame_counts[0]} frames @ {args.fps} fps, {len(cameras)} cameras) to {out_path}"
    )


if __name__ == "__main__":
    main()
